#include "material_blend_candidate.h"
#include <fstream>
#include <iostream>
int main(int argc,char**argv){try{static_assert(sizeof(void*)==8,"x64 required");if(materialTranslucentCandidate(parseVmtCandidate("shader {}"))||materialTranslucentCandidate(parseVmtCandidate("shader {$translucent 0}"))||!materialTranslucentCandidate(parseVmtCandidate("shader {$TRANSLUCENT \"1\"}")))throw std::runtime_error("blend flags");size_t rejected=0;for(auto source:{"shader {$translucent 2}","shader {$translucent 1 $translucent 0}"}){try{materialTranslucentCandidate(parseVmtCandidate(source));}catch(const std::runtime_error&){++rejected;}}if(rejected!=2||argc!=2)throw std::runtime_error("blend rejection/fixture");std::ifstream f(argv[1]);if(!f)throw std::runtime_error("fixture missing");std::string source((std::istreambuf_iterator<char>(f)),{});if(!materialTranslucentCandidate(parseVmtCandidate(source)))throw std::runtime_error("installed translucent flag");std::cout<<"x64 material blend flags passed rejected="<<rejected<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
